//! The registry of diagnostic codes (decision A6 of `design/analyzer-design.md`).
//!
//! One canonical code per condition, owned by the brief of its area, plus the
//! aliases under which the other briefs name the same condition. The codes
//! are statics, one file per brief so that engineers don't conflict; the
//! three brief files are generated by `scripts/extract-codes.py`.
//!
//! ```
//! use fa_analyzer::diagnostics::codes;
//!
//! let code = codes::lookup("EF015").unwrap(); // an alias
//! assert_eq!(code.id, "E-ERR-3");
//! assert!(std::ptr::eq(code, &codes::values::E_ERR_3));
//! ```

use rustc_hash::FxHashMap;
use std::sync::OnceLock;

use crate::diagnostics::CodeInfo;

/// Declares code statics and the `ALL` list of a registry file.
///
/// `NAME = "ID", Severity, ["ALIAS", …], "summary";`
macro_rules! codes {
	($($name:ident = $id:literal, $severity:ident, [$($alias:literal),* $(,)?], $summary:literal;)*) => {
		$(
			#[doc = concat!("`", $id, "`: ", $summary)]
			pub static $name: crate::diagnostics::CodeInfo = crate::diagnostics::CodeInfo {
				id: $id,
				aliases: &[$($alias),*],
				severity: $severity,
				summary: $summary,
			};
		)*

		/// Every code of this file.
		pub static ALL: &[&crate::diagnostics::CodeInfo] = &[$(&$name),*];
	};
}

pub mod advanced;
pub mod analyzer;
pub mod types;
pub mod values;

/// The code lists of every registry file.
pub fn registries() -> [&'static [&'static CodeInfo]; 4] {
	[values::ALL, types::ALL, advanced::ALL, analyzer::ALL]
}

/// Every code of the registry.
pub fn all() -> impl Iterator<Item = &'static CodeInfo> {
	registries().into_iter().flatten().copied()
}

/// The code whose id or one of whose aliases is `name`.
pub fn lookup(name: &str) -> Option<&'static CodeInfo> {
	static INDEX: OnceLock<FxHashMap<&'static str, &'static CodeInfo>> = OnceLock::new();
	let index = INDEX.get_or_init(|| {
		let mut index = FxHashMap::default();
		for code in all() {
			index.insert(code.id, code);
			for &alias in code.aliases {
				index.insert(alias, code);
			}
		}
		index
	});
	index.get(name).copied()
}

#[cfg(test)]
mod tests {
	use rustc_hash::FxHashSet;

	use super::*;
	use crate::diagnostics::Severity;

	#[test]
	fn no_id_or_alias_appears_twice() {
		let mut seen = FxHashSet::default();
		for code in all() {
			assert!(seen.insert(code.id), "{} defined twice", code.id);
			for alias in code.aliases {
				assert!(
					seen.insert(*alias),
					"{alias} used twice (alias of {})",
					code.id
				);
			}
		}
	}

	#[test]
	fn every_code_has_a_summary() {
		for code in all() {
			assert!(!code.summary.is_empty(), "{} has no summary", code.id);
		}
	}

	#[test]
	fn codes_live_in_the_file_of_their_brief() {
		let is_values = |id: &str| id.starts_with("E-") || id.starts_with("W-");
		assert!(values::ALL.iter().all(|code| is_values(code.id)));
		assert!(types::ALL.iter().all(|code| !is_values(code.id)));
		assert!(advanced::ALL.iter().all(|code| !is_values(code.id)));
		assert!(analyzer::ALL.iter().all(|code| code.id.starts_with("AN")));
	}

	#[test]
	fn aliases_resolve_to_their_canonical_code() {
		for (alias, canonical) in [
			("EF015", "E-ERR-3"),
			("EF030", "REF013"),
			("E-DECL-16", "REF001"),
			("FN010", "EFF020"),
			("CV001", "E-NUM-11"),
			("CL060", "E-NUM-17"),
			("WEF002", "W-ERR-1"),
			("E-TYPE-2", "TY040"),
			("TY002", "E-TYPE-1"),
			("TEST001", "E-BOOL-1"),
			("TY009", "E-DECL-2"),
			("FN001", "E-DECL-6"),
			("FN014", "E-DO-2"),
			("TY070", "E-DECL-9"),
			("EF041", "EFF008"),
			("EF044", "EFF009"),
			("WEF001", "EFF011"),
			("EF016", "REQ001"),
		] {
			assert_eq!(
				lookup(alias).map(|code| code.id),
				Some(canonical),
				"{alias}"
			);
		}
		assert_eq!(lookup("E-NUM-10").map(|code| code.id), Some("E-NUM-10"));
		assert!(lookup("E-NUM-999").is_none());
	}

	#[test]
	fn severities_follow_the_briefs() {
		assert_eq!(lookup("W-DO-2").unwrap().severity, Severity::Warning);
		assert_eq!(lookup("WTY001").unwrap().severity, Severity::Warning);
		assert_eq!(lookup("EFF011").unwrap().severity, Severity::Warning);
		assert_eq!(lookup("MOD013").unwrap().severity, Severity::Warning);
		assert_eq!(lookup("E-NUM-10").unwrap().severity, Severity::Error);
		assert_eq!(lookup("REF001").unwrap().severity, Severity::Error);
	}

	#[test]
	fn the_registry_covers_every_brief() {
		assert!(values::ALL.len() > 150);
		assert!(types::ALL.len() > 150);
		assert!(advanced::ALL.len() >= 150);
	}
}
